<template>
  <div class="sl-root">
    <main class="sl-body">
      <section class="sl-card">
        <!-- ── Card header ──────────────────────────────────────────── -->
        <div class="sl-card__head">
          <div class="sl-card__head-left">
            <div class="sl-card__chip">EXCHANGE</div>
            <h2 class="sl-card__title">Staff Exchange Requests</h2>
          </div>
          <div class="sl-card__head-right">
            <span class="sl-card__sub" v-if="!loading">
              {{ filteredRequests.length }} of
              {{ requests.length }} records
            </span>
            <v-btn
              color="primary"
              small
              depressed
              class="ml-4"
              @click="newRequest"
            >
              <v-icon small left>mdi-plus</v-icon>
              New Exchange Request
            </v-btn>
          </div>
        </div>

        <!-- ── Loading ──────────────────────────────────────────────── -->
        <div v-if="loading" class="sl-loading">
          <v-progress-circular
            indeterminate
            color="primary"
            size="48"
          ></v-progress-circular>
          <span>Loading exchange requests…</span>
        </div>

        <template v-else>
          <!-- ── Filters ─────────────────────────────────────────────── -->
          <v-card-text class="pb-1 pt-3">
            <v-row dense>
              <v-col cols="12" sm="6" md="4">
                <v-text-field
                  v-model="filter.name"
                  label="Search staff name"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-magnify"
                  class="ma-1"
                  @input="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="6" md="3">
                <v-select
                  v-model="filter.status"
                  :items="statusOptions"
                  label="Status"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-progress-check"
                  class="ma-1"
                  @change="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="auto" class="d-flex align-center">
                <v-btn
                  v-if="hasActiveFilters"
                  text
                  small
                  color="red darken-1"
                  class="ma-1"
                  @click="resetFilters"
                >
                  <v-icon small left>mdi-close</v-icon>
                  Clear filters
                </v-btn>
              </v-col>
            </v-row>
          </v-card-text>

          <!-- ── Error banner ────────────────────────────────────────── -->
          <v-alert
            v-if="loadError"
            type="warning"
            dense
            outlined
            class="mx-4 mb-2"
          >
            {{ loadError }}
          </v-alert>

          <!-- ── Data table ──────────────────────────────────────────── -->
          <v-data-table
            :headers="tableHeaders"
            :items="filteredRequests"
            :items-per-page="15"
            :footer-props="{
              'items-per-page-options': [10, 15, 25, 50],
              'items-per-page-text': 'Rows per page',
            }"
            no-data-text="No exchange requests match the current filters"
            class="elevation-0"
            @click:row="viewRequest"
          >
            <template #[`item.requesterName`]="{ item }">
              <div class="sl-table__primary">{{ item.requesterName }}</div>
              <span class="sl-table__muted">{{ item.requesterPosition }}</span>
            </template>

            <template #[`item.partnerName`]="{ item }">
              <div class="sl-table__primary">{{ item.partnerName }}</div>
              <span class="sl-table__muted">{{ item.partnerPosition }}</span>
            </template>

            <template #[`item.plannedTransferDate`]="{ item }">
              <span class="sl-table__muted">{{
                formatDate(item.plannedTransferDate)
              }}</span>
            </template>

            <template #[`item.eventDate`]="{ item }">
              <span class="sl-table__muted">{{
                formatDate(item.eventDate)
              }}</span>
            </template>

            <template #[`item.status`]="{ item }">
              <span
                class="sl-status-pill"
                :class="'sl-status-pill--' + statusKey(item.status)"
              >
                <span class="sl-status-pill__dot"></span>
                {{ item.statusDisplay }}
              </span>
            </template>

            <template #[`item.actions`]="{ item }">
              <v-btn icon small @click.stop="viewRequest(item)">
                <v-icon small>mdi-eye-outline</v-icon>
              </v-btn>
            </template>
          </v-data-table>
        </template>
      </section>
    </main>

    <v-snackbar v-model="snackbar.show" :color="snackbar.color" top right :timeout="4000">
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";

export default {
  name: "StaffExchangeList",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      loading: true,
      loadError: null,
      requests: [],
      positionsMap: {},

      filter: { name: "", status: null },
      filterDebounce: null,
      filteredRequests: [],

      statusValueSetItems: [],

      tableHeaders: [
        { text: "Requester", value: "requesterName", width: "220px" },
        { text: "Exchanging With", value: "partnerName", width: "220px" },
        {
          text: "Planned Exchange Date",
          value: "plannedTransferDate",
          sortable: false,
        },
        { text: "Submitted", value: "eventDate", sortable: false },
        { text: "Status", value: "status", sortable: false },
        { text: "", value: "actions", sortable: false, width: "80px" },
      ],

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    statusOptions() {
      return this.statusValueSetItems.map((item) => ({
        text: item.display || item.code,
        value: item.code,
      }));
    },

    hasActiveFilters() {
      return !!this.filter.name || !!this.filter.status;
    },
  },

  async mounted() {
    await Promise.all([this.loadStatusValueSet(), this.loadRequests()]);
  },

  methods: {
    async loadStatusValueSet() {
      try {
        // Scoped to staff exchange's own statuses — the unscoped
        // request-status-valueset also carries HOD Recommended Transfer's
        // statuses (underhodreview, supervisorrejected, ...), which don't
        // apply here and would confuse the filter.
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/staff-location-exchange-request-status-valueset",
        );
        this.statusValueSetItems = items || [];
      } catch (err) {
        console.error("loadStatusValueSet error:", err);
      }
    },

    // Extension urls come from the *Extension definition's* id, not the FSH
    // slice name — try the canonical id(s) first, fall back to the slice
    // name in case the upstream IG source is corrected later.
    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    // Resolve one position's designation directly by id (mirrors the HOD
    // Recommended Transfer list page — avoids the /site/position/report
    // endpoint's 100-item server-side cap silently dropping positions).
    async resolvePosition(ref) {
      if (!ref) return {};
      if (this.positionsMap[ref]) return this.positionsMap[ref];
      try {
        const id = ref.includes("/") ? ref.split("/")[1] : ref;
        const res = await fetch(`/fhir/Basic/${id}`);
        if (!res.ok) return {};
        const position = await res.json();
        const getExt = (part, type) =>
          position.extension?.find((e) => e.url.includes(part))?.[type];

        let designation = "";
        const designationRef = getExt("designation", "valueReference")
          ?.reference;
        if (designationRef) {
          try {
            const dId = designationRef.split("/")[1];
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const dData = await dRes.json();
            designation =
              dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || "";
          } catch {
            // designation lookup best-effort
          }
        }

        const result = { designation };
        this.positionsMap[ref] = result;
        return result;
      } catch (err) {
        console.error("resolvePosition error:", err);
        return {};
      }
    },

    async loadRequests() {
      this.loading = true;
      this.loadError = null;
      try {
        this.positionsMap = {};

        // Wait for generalMixin to finish loading loggedInStaff
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        // Scoped server-side: own requests, plus (for HR Director, District
        // HR, District HOD or Departmental Director) whatever falls under
        // that reviewer's coverage. See routes/general.js
        // GET /staffExchangeRequests — filtering by "am I the requester or
        // partner" client-side, as this used to do, only hid rows from the
        // page; the raw /fhir/Basic search was still reachable directly by
        // anyone with read access to Basic.
        const res = await fetch(`/site/general/staffExchangeRequests`);
        const bundle = await res.json();
        let resources = (bundle.entry || []).map((e) => e.resource);

        const practRefs = [
          ...new Set(
            resources
              .flatMap((r) => [
                this.getExt(r, ["ihris-practitioner-reference", "practitioner"])
                  ?.valueReference?.reference,
                this.getExt(r, "staff-exchanging-with")?.valueReference
                  ?.reference,
              ])
              .filter(Boolean),
          ),
        ];

        const nameMap = {};
        await Promise.all(
          practRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        const positionRefs = [
          ...new Set(
            resources.flatMap((r) => [
              this.getExt(r, ["position-reference", "current-position"])
                ?.valueReference?.reference,
              this.getExt(r, ["destination-position", "destition-position"])
                ?.valueReference?.reference,
            ]),
          ),
        ].filter(Boolean);

        await Promise.all(positionRefs.map((ref) => this.resolvePosition(ref)));

        this.requests = resources.map((r) => {
          const requesterRef = this.getExt(r, [
            "ihris-practitioner-reference",
            "practitioner",
          ])?.valueReference?.reference;
          const partnerRef = this.getExt(r, "staff-exchanging-with")
            ?.valueReference?.reference;
          const curRef = this.getExt(r, [
            "position-reference",
            "current-position",
          ])?.valueReference?.reference;
          const destRef = this.getExt(r, [
            "destination-position",
            "destition-position",
          ])?.valueReference?.reference;
          const cur = this.positionsMap[curRef] || {};
          const dest = this.positionsMap[destRef] || {};
          const statusCoding = this.getExt(r, ["request-status", "status"])
            ?.valueCoding;
          const eventDate =
            this.getExt(r, "event-date")?.valueDate || r.meta?.lastUpdated;

          return {
            id: r.id,
            requesterName: nameMap[requesterRef] || "Unknown",
            requesterPosition: cur.designation || "",
            partnerName: nameMap[partnerRef] || "Unknown",
            partnerPosition: dest.designation || "",
            plannedTransferDate: this.getExt(r, "planned-transfer-date")
              ?.valueDate,
            transferReason: this.getExt(r, ["reason", "transfer-reason"])
              ?.valueString,
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            eventDate,
          };
        });

        this.requests.sort(
          (a, b) => new Date(b.eventDate || 0) - new Date(a.eventDate || 0),
        );

        this.applyFilters();
      } catch (err) {
        console.error("loadRequests error:", err);
        this.loadError =
          "Some records could not be loaded. Showing partial results.";
      } finally {
        this.loading = false;
      }
    },

    applyFilters() {
      const name = (this.filter.name || "").toLowerCase().trim();
      const status = this.filter.status;

      this.filteredRequests = this.requests.filter((row) => {
        if (
          name &&
          !row.requesterName.toLowerCase().includes(name) &&
          !row.partnerName.toLowerCase().includes(name)
        ) {
          return false;
        }
        if (status && row.status !== status) return false;
        return true;
      });
    },

    onFilterChange() {
      clearTimeout(this.filterDebounce);
      this.filterDebounce = setTimeout(() => this.applyFilters(), 250);
    },

    resetFilters() {
      this.filter = { name: "", status: null };
      this.applyFilters();
    },

    newRequest() {
      this.$router.push({
        path: "/custom/staff-exchange-request",
        query: { path: "/lesotho/components/transfers" },
      });
    },

    viewRequest(item) {
      this.$router.push({
        path: "/custom/staff-exchange-view",
        query: {
          path: "/lesotho/components/transfers",
          id: item.id,
          returnLabel: "Back to Exchange Requests",
        },
      });
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved") return "done";
      if (status && status.includes("rejected")) return "error";
      if (status === "cancelled") return "none";
      if (status && status.includes("review")) return "active";
      return "warn";
    },

    formatDate(dateString) {
      if (!dateString) return "—";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "—";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },
  },
};
</script>

